hooks.command:
node -e '
let d = "";
process.stdin.on("data", c => d += c);
process.stdin.on("end", () => {
  let input;
  try { input = JSON.parse(d); } catch { process.exit(0); }
  const f = input.tool_input && input.tool_input.file_path;
  if (!f || !f.endsWith(".js")) process.exit(0);
  const { execSync } = require("child_process");
  try {
    execSync(`node --check "${f}"`, { stdio: "pipe" });
  } catch (e) {
    const lines = (e.stderr || e.message || "").toString().split("\n").filter(Boolean).slice(0, 3).join(" | ");
    console.log(JSON.stringify({ systemMessage: "Warning: node --check failed for " + f + " -- " + lines }));
  }
});
'
